"""Hidden behavioral tests for cmark: smart. Generated by pbkit from the gold binary."""


def test_smart_01(run):
    r = run(args=['--smart'], stdin=b'"Hello," said the spider.\n"\'Shelob\' is my name."\n')
    assert r.stdout == b'<p>\xe2\x80\x9cHello,\xe2\x80\x9d said the spider.\n\xe2\x80\x9c\xe2\x80\x98Shelob\xe2\x80\x99 is my name.\xe2\x80\x9d</p>\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_smart_01_off(run):
    r = run(args=[], stdin=b'"Hello," said the spider.\n"\'Shelob\' is my name."\n')
    assert r.stdout == b"<p>&quot;Hello,&quot; said the spider.\n&quot;'Shelob' is my name.&quot;</p>\n"
    assert r.stderr == b''
    assert r.returncode == 0


def test_smart_01_latex(run):
    r = run(args=['--smart', '-t', 'latex'], stdin=b'"Hello," said the spider.\n"\'Shelob\' is my name."\n')
    assert r.stdout == b"``Hello,'' said the spider.\n```Shelob' is my name.''\n"
    assert r.stderr == b''
    assert r.returncode == 0


def test_smart_01_commonmark(run):
    r = run(args=['--smart', '-t', 'commonmark'], stdin=b'"Hello," said the spider.\n"\'Shelob\' is my name."\n')
    assert r.stdout == b'\xe2\x80\x9cHello,\xe2\x80\x9d said the spider.\n\xe2\x80\x9c\xe2\x80\x98Shelob\xe2\x80\x99 is my name.\xe2\x80\x9d\n'
