def test_code_latex_smart(run):
    r = run(args=['-t', 'latex', '--smart'], stdin=b'``` js {.class}\nconsole.log(`x`);\n```\n\n~~~~\n~~~\n~~~~\n\n`` a`b ``\n\n````\n```\n````\n')
    assert r.stdout == b'\\begin{verbatim}\nconsole.log(`x`);\n\\end{verbatim}\n\n\\begin{verbatim}\n~~~\n\\end{verbatim}\n\n\\texttt{a`b}\n\n\\begin{verbatim}\n```\n\\end{verbatim}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_breaks_html_smart(run):
    r = run(args=['--smart'], stdin=b'line one\nline two  \nline three\\\nline four\n')
    assert r.stdout == b'<p>line one\nline two<br />\nline three<br />\nline four</p>\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_breaks_xml_smart(run):
    r = run(args=['-t', 'xml', '--smart'], stdin=b'line one\nline two  \nline three\\\nline four\n')
    assert r.stdout == b'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE document SYSTEM "CommonMark.dtd">\n<document xmlns="http://commonmark.org/xml/1.0">\n  <paragraph>\n    <text xml:space="preserve">line one</text>\n    <softbreak />\n    <text xml:space="preserve">line two</text>\n    <linebreak />\n    <text xml:space="preserve">line three</text>\n    <linebreak />\n    <text xml:space="preserve">line four</text>\n  </paragraph>\n</document>\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_breaks_man_smart(run):
    r = run(args=['-t', 'man', '--smart'], stdin=b'line one\nline two  \nline three\\\nline four\n')
    assert r.stdout == b'.PP\nline one\nline two.PD 0\n.P\n.PD\nline three.PD 0\n.P\n.PD\nline four\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_breaks_commonmark_smart(run):
    r = run(args=['-t', 'commonmark', '--smart'], stdin=b'line one\nline two  \nline three\\\nline four\n')
    assert r.stdout == b'line one\nline two  \nline three  \nline four\n'
