def test_unicode_html_smart(run):
    r = run(args=['--smart'], stdin=b'\xc3\x9cn\xc3\xafc\xc3\xb6d\xc3\xa9 \xe2\x80\x94 \xe2\x80\x9cquotes\xe2\x80\x9d \xe2\x80\x98single\xe2\x80\x99 \xe6\x97\xa5\xe6\x9c\xac\xe8\xaa\x9e *\xe5\xbc\xb7\xe8\xaa\xbf* \xf0\x9f\x98\x80 \xc2\xa0nbsp\n')
    assert r.stdout == b'<p>\xc3\x9cn\xc3\xafc\xc3\xb6d\xc3\xa9 \xe2\x80\x94 \xe2\x80\x9cquotes\xe2\x80\x9d \xe2\x80\x98single\xe2\x80\x99 \xe6\x97\xa5\xe6\x9c\xac\xe8\xaa\x9e <em>\xe5\xbc\xb7\xe8\xaa\xbf</em> \xf0\x9f\x98\x80 \xc2\xa0nbsp</p>\n'
    assert r.stderr == b''
    assert r.returncode == 0


