def test_nested_structure_html_smart(run):
    r = run(args=['--smart'], stdin=b'> 1. > - a\n>    >   b\n> 2. c\n>\n>        code in list\n')
    assert r.stdout == b'<blockquote>\n<ol>\n<li>\n<blockquote>\n<ul>\n<li>a\nb</li>\n</ul>\n</blockquote>\n</li>\n<li>\n<p>c</p>\n<pre><code>code in list\n</code></pre>\n</li>\n</ol>\n</blockquote>\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_nested_structure_xml_smart(run):
    r = run(args=['-t', 'xml', '--smart'], stdin=b'> 1. > - a\n>    >   b\n> 2. c\n>\n>        code in list\n')
    assert r.stdout == b'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE document SYSTEM "CommonMark.dtd">\n<document xmlns="http://commonmark.org/xml/1.0">\n  <block_quote>\n    <list type="ordered" start="1" delim="period" tight="false">\n      <item>\n        <block_quote>\n          <list type="bullet" tight="true">\n            <item>\n              <paragraph>\n                <text xml:space="preserve">a</text>\n                <softbreak />\n                <text xml:space="preserve">b</text>\n              </paragraph>\n            </item>\n          </list>\n        </block_quote>\n      </item>\n      <item>\n        <paragraph>\n          <text xml:space="preserve">c</text>\n        </paragraph>\n        <code_block xml:space="preserve">code in list\n</code_block>\n      </item>\n    </list>\n  </block_quote>\n</document>\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_nested_structure_man_smart(run):
    r = run(args=['-t', 'man', '--smart'], stdin=b'> 1. > - a\n>    >   b\n> 2. c\n>\n>        code in list\n')
    assert r.stdout == b'.RS\n.IP "1." 4\n.RS\n.RS\n.IP \\[bu] 2\na\nb\n.RE\n.RE\n.IP "2." 4\nc\n.RS\n.IP\n.nf\n\\f[C]\ncode in list\n\\f[]\n.fi\n.RE\n.RE\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_nested_structure_commonmark_smart(run):
    r = run(args=['-t', 'commonmark', '--smart'], stdin=b'> 1. > - a\n>    >   b\n> 2. c\n>\n>        code in list\n')
    assert r.stdout == b'> 1.  >   - a\n>     >     b\n> \n> 2.  c\n>     \n>     ``` \n>     code in list\n>     ```\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_nested_structure_latex_smart(run):
    r = run(args=['-t', 'latex', '--smart'], stdin=b'> 1. > - a\n>    >   b\n> 2. c\n>\n>        code in list\n')
    assert r.stdout == b'\\begin{quote}\n\\begin{enumerate}\n\\item \\begin{quote}\n\\begin{itemize}\n\\item a\nb\n\n\\end{itemize}\n\n\\end{quote}\n\n\\item c\n\n\\begin{verbatim}\ncode in list\n\\end{verbatim}\n\n\\end{enumerate}\n\n\\end{quote}\n'
    assert r.stderr == b''
    assert r.returncode == 0
